import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"33、【遁】 艮下乾上","description":"周易尚氏学 - 33、【遁】 艮下乾上","frontmatter":{"title":"33、【遁】 艮下乾上","description":"周易尚氏学 - 33、【遁】 艮下乾上"},"headers":[],"relativePath":"zh/classics/shangshi/038.md","filePath":"zh/classics/shangshi/038.md"}'),h={name:"zh/classics/shangshi/038.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_33、【遁】-艮下乾上" tabindex="-1">33、【遁】 艮下乾上 <a class="header-anchor" href="#_33、【遁】-艮下乾上" aria-label="Permalink to “33、【遁】 艮下乾上”">​</a></h1><p>遁月卦辟未。阴长阳消。小人道长。君子道消。遁者退也。避也。当阴盛之时。势须退避。否则其祸有不可胜言者矣。故曰遁亨。盖以行止论。洁身退隐。否所谓俭德避难也。无所谓亨。而以祸福论。防微虑远。不事王侯。高尚其事。优游事外。亨莫亨于是矣。故传日适而亨也。阳大阴小。小利贞者。谓宜贞定也。传曰浸而长。谓阴方长。长则消阳。故利于静。不利于动也。</p><p>彖曰。遁亨。通而亨也。刚当位而应。与时行也。小利贞。浸而长也。通之时义大矣哉。</p><p>五当位。二有应。故曰刚当位而应。然而不能不适者。时不可也。故曰与时行。遁太早则有过情之讥。如严光是也。太晚则不能适。沉溺于小人之中。而不能免。如刘歆是也。行而宜之之谓义。故夫子极叹时义之大。</p><p>象曰。天下有山。遁。君子以远小人。不恶而严。</p><p>凡卦皆合上下卦以立名。乾健艮止。皆无退义。然而遁者。以乾与艮先后天皆居西北也。西北者幽潜无用之地。太玄谓曰冥。冥者明之藏也。故曰遁。乾为君子。远遁在外。故曰远小人。五应二。故曰不恶。然以有阻隔故。绝难为与。故曰不恶而严。盖外不与绝。内实远之也。</p><p>初六。通尾。厉。勿用有攸往。</p><p>爻象初为尾。初往应四。则为同性之二所阻。危厉之道也。勿往则免矣。</p><h3 id="象曰。遁尾之厉。不往何灾也。" tabindex="-1">象曰。遁尾之厉。不往何灾也。 <a class="header-anchor" href="#象曰。遁尾之厉。不往何灾也。" aria-label="Permalink to “象曰。遁尾之厉。不往何灾也。”">​</a></h3><p>艮为止。在艮宜静。勿用有攸往。则无灾矣。</p><p>六二。执之用黄牛之革。莫之胜说。</p><p>艮为牛。无妄六三或系之牛是也。二居中。故曰黄牛。易林既济之艮云。伺候牛羊。同人之无妄云。负牛上山。皆以艮为牛。艮为皮革。执持也止也。艮手为执。言二得中正。宜贞定自持。如牛革之固。莫能胜我而说去也。仍小利贞之怡（右下日）也。说脱同。</p><h3 id="象曰。执用黄牛。固态也。" tabindex="-1">象曰。执用黄牛。固态也。 <a class="header-anchor" href="#象曰。执用黄牛。固态也。" aria-label="Permalink to “象曰。执用黄牛。固态也。”">​</a></h3><p>巽为志。牛革者至固之物。持志如是。贞定极矣。故曰固志。固则不动。不动则不消阳。</p><p>九三。系遁。有疾厉。畜臣妾。吉。</p><p>巽为绳。故曰系。艮止故曰秒遁。言系恋而不即遁也。巽为疾。三无应。往遇敌。故有疾厉。然下有重阴。承顺于三。畜臣妾则吉。艮为臣妾也。巽疾象。详履卦象传注。艮臣象亦本易林。易林决（无左）之坎云。君臣扰忧。坎中爻艮震。震为君。艮为臣。故曰君臣扰忧。又兑之艮云。臣围其君。亦以艮为臣。盖艮为憧为仆。故为妾。臣与仆古不分。故为臣。由是知蹇六二曰。王臣塞蹇。小过六二曰。遇其巨。易原以艮为臣也。</p><h3 id="象曰。系遭之厉。有疾惫也。畜臣妾吉。不可大事也。" tabindex="-1">象曰。系遭之厉。有疾惫也。畜臣妾吉。不可大事也。 <a class="header-anchor" href="#象曰。系遭之厉。有疾惫也。畜臣妾吉。不可大事也。" aria-label="Permalink to “象曰。系遭之厉。有疾惫也。畜臣妾吉。不可大事也。”">​</a></h3><p>广韵。惫赢困也。陆绩云。大事谓天下之政。潜道之世。但可居家。畜养臣妾。不可治国之大事。</p><p>九四。好遁。君子吉。小人否。</p><p>虞翻曰。否乾为好为君子。阴称小人。按四与初有应。好适者。外不与小人绝。当祸患未形之时。从容而遁也。然知几其神。惟君子能之。若小人则系恋而不去也。故曰君子吉。小人否。</p><h3 id="象曰。君子好遁。小人否也。" tabindex="-1">象曰。君子好遁。小人否也。 <a class="header-anchor" href="#象曰。君子好遁。小人否也。" aria-label="Permalink to “象曰。君子好遁。小人否也。”">​</a></h3><p>否不也。小人不肯退。不退则凶咎至矣。</p><p>九五。嘉遁。贞吉。</p><p>乾为嘉。五居中当位。下有应与。大必适也。乃识微虑远。及此嘉时而遁焉。故曰贞吉。</p><h3 id="象曰。嘉遁贞吉。以王志也。" tabindex="-1">象曰。嘉遁贞吉。以王志也。 <a class="header-anchor" href="#象曰。嘉遁贞吉。以王志也。" aria-label="Permalink to “象曰。嘉遁贞吉。以王志也。”">​</a></h3><p>五应在二。二互巽。巽为伏。故为心志。虞翻用卦变谓四与初巳易位。三已变成坎。上来之三。成坎为志。夫圣人观象系辞。其所用象。乃在三变之后。迂曲如此。使后学鸟从测之哉。</p><p>上九。肥通。无不利。</p><p>子夏传释肥为饶裕。虞翻以乾盈为肥。皆非。后汉张衡传。注引淮南九师训云。飞而能适。吉孰大焉。易林需之遁云。去如飞鸿。节之道云。奋翅鼓翼。王弼云。曾（左矢）缴不能及。并皆读为飞。朱芹引姚宽西溪丛语云。肥古作琶。琶蜚同字。是肥即蜚。蜚即飞也。盖上九居极上。高飞远引。无有阻隔。故无不利。而乾为行。故为飞。乾九五飞龙在天是也。</p><h3 id="象曰。肥遁无不利。无所疑也。" tabindex="-1">象曰。肥遁无不利。无所疑也。 <a class="header-anchor" href="#象曰。肥遁无不利。无所疑也。" aria-label="Permalink to “象曰。肥遁无不利。无所疑也。”">​</a></h3><p>上九逍遥世外。故无所疑。</p>',30)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
